package sao.zh.compat16;
import java.io.*;
import java.util.Base64;
import java.util.zip.GZIPInputStream;
import java.security.MessageDigest;
/** Generated from the three exact release assets. No filesystem, network, or classloader resource lookup. */
final class SplashAssets {
 private SplashAssets(){}
 static byte[] read(String name)throws IOException {
  switch(name){
   case "zh_tw.json":return unpack(new String[]{""},5261,"dbdb4818b0ea754e8a4b6b0980ff0cedda084558f97ae77f4a8661fe28910749");
   case "atlas.json":return unpack(new String[]{""},12580,"3f0ae85ec7147e19da2419f65c4c7e8c6b2ad7f329e3257b64dafdcb62c24dfc");
   case "atlas.png":return unpack(new String[]{"","","","","","","","","","","","","","","","","","","","","",""},194508,"7030a27e975af36c1d49b8913cc3b8ecd159a314fb2d286619a839ad856e9b52");
   default:throw new FileNotFoundException("Unknown startup asset: "+name);
  }
 }
 private static byte[] unpack(String[] parts,int expected,String sha)throws IOException {
  StringBuilder all=new StringBuilder();for(String part:parts)all.append(part);
  byte[] zipped;try{zipped=Base64.getDecoder().decode(all.toString());}catch(IllegalArgumentException e){throw new IOException("Invalid startup payload",e);}
  try(InputStream in=new GZIPInputStream(new ByteArrayInputStream(zipped));ByteArrayOutputStream out=new ByteArrayOutputStream(expected)){
   byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>expected||out.size()+n>2097152)throw new IOException("Oversized startup payload");out.write(buffer,0,n);}
   byte[] result=out.toByteArray();if(result.length!=expected)throw new IOException("Incomplete startup payload");
   try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(result);StringBuilder hex=new StringBuilder();for(byte b:digest)hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));if(!sha.contentEquals(hex))throw new IOException("Startup payload hash mismatch");}
   catch(java.security.NoSuchAlgorithmException e){throw new IOException("SHA-256 unavailable",e);}
   return result;
  }
 }
}
